def mappick_sql(self, expression: exp.MapPick) -> str:
    map_arg = expression.this
    keys = expression.expressions
    x_dot_key = exp.Dot(this=exp.to_identifier("x"), expression=exp.to_identifier("key"))

    if len(keys) == 1 and (isinstance(keys[0], exp.Array) or keys[0].is_type(exp.DType.ARRAY)):
        predicate = exp.func("ARRAY_CONTAINS", keys[0], x_dot_key)
    else:
        predicate = exp.In(this=x_dot_key, expressions=keys)

    result = exp.func(
        "MAP_FROM_ENTRIES",
        exp.ArrayFilter(
            this=exp.func("MAP_ENTRIES", map_arg),
            expression=exp.Lambda(this=predicate, expressions=[exp.to_identifier("x")]),
        ),
    )
    return self.sql(result)

def mapsize_sql(self, expression: exp.MapSize) -> str:
    return self.func("CARDINALITY", expression.this)
